WITH exploded AS (SELECT id, EXPLODE_OUTER(coupon_codes) AS tag FROM carts), filtered AS (SELECT *, SUBSTRING(tag, 1, 4) AS tag_prefix, COALESCE(tag, 'UNKNOWN') AS tag_filled FROM exploded WHERE tag IS NOT NULL), base AS (SELECT *, TRIM(tag) AS clean_tag, COALESCE(tag, 'N/A') AS resolved_tag FROM filtered WHERE tag = 'VIP'), valid AS (SELECT *, LOWER(tag) AS tag_lower, UPPER(tag) AS tag_upper FROM base WHERE tag IN ('SPRING10', 'WELCOME5', 'VIP')), base_carts AS (SELECT tag, tag_prefix, tag_filled, clean_tag, resolved_tag, tag_lower, LENGTH(tag) AS tag_length, COALESCE(tag, 'N/A') AS tag_clean FROM valid WHERE tag IS NOT NULL), cleaned AS (SELECT tag, tag_prefix, clean_tag, tag_length, tag_clean, INITCAP(TRIM(tag)) AS tag_title, CASE WHEN tag_length >= 77 THEN 'High' WHEN tag_length >= 23 THEN 'Medium' ELSE 'Low' END AS tag_length_level FROM base_carts WHERE tag IS NOT NULL AND tag IN ('WELCOME5', 'BUNDLE', 'SPRING10')), valid_carts AS (SELECT tag, tag_prefix, tag_title, tag_length_level, CASE WHEN tag_length >= 74 THEN 'High' WHEN tag_length >= 29 THEN 'Medium' ELSE 'Low' END AS tag_length_tier FROM cleaned WHERE tag IN ('BUNDLE', 'VIP')), daily AS (SELECT tag, SIZE(COLLECT_SET(tag)) AS num_tags, COUNT_IF(tag = 'WELCOME5') AS welcome5_events, COUNT(*) FILTER (WHERE tag = 'VIP') AS vip_rows FROM valid_carts GROUP BY tag) SELECT tag, num_tags, welcome5_events, vip_rows FROM daily ORDER BY tag DESC NULLS FIRST
